//! The differential harness (1.5.0): the binary against the Python
//! reference's verdicts and reason codes. A difference is a bug in one of
//! them, resolved against the spec.
//!
//! * the shared suites in `tests/fixtures` (generated by the reference) and
//!   the anchors fixture (`scripts/generate_anchor_vectors.py`) always run;
//! * `GM_VERIFY_CORPUS=<dir>` also runs the core's verification corpus, the
//!   `verification/` directory `scripts/export_reference_corpus.py --suite
//!   verification` writes: every case of its `corpus.json` (records, exports,
//!   key histories and packs), and its copies of the conformance suites must
//!   be this crate's fixtures byte for byte. A file instead holds suites: one
//!   (`{"suite", "vectors"}`), a list of them, or `{"suites": [...]}`. Cases
//!   without an adapter are reported as skipped; with
//!   `GM_VERIFY_CORPUS_STRICT=1` a skip fails the run.
//!
//! `GM_VERIFY_BINARY=<path>` runs another build of the binary, such as a
//! static release binary.

mod adapter;
mod common;

use adapter::{adapt, adapt_corpus, expected, project, Adapted, Case};
use common::{fixture, run, Scratch};
use serde_json::Value;

#[derive(Default)]
struct Tally {
    ran: usize,
    skipped: Vec<String>,
    failed: Vec<String>,
}

fn run_suite(suite: &Value, tally: &mut Tally) {
    let name = suite["suite"].as_str().unwrap_or("unnamed");
    for v in suite["vectors"].as_array().into_iter().flatten() {
        let id = format!("{name}/{}", v["id"].as_str().unwrap_or("?"));
        let scratch = Scratch::new(name);
        check(&id, adapt(name, v, &scratch), tally);
    }
}

/// Run one adapted case and compare its result with the reference's.
fn check(id: &str, adapted: Adapted, tally: &mut Tally) {
    let case: Case = match adapted {
        Adapted::Run(case) => case,
        Adapted::Computed { got, expected } => {
            tally.ran += 1;
            if got != expected {
                tally
                    .failed
                    .push(format!("{id}:\n  expected {expected}\n  got      {got}"));
            }
            return;
        }
        Adapted::Skip(why) => {
            tally.skipped.push(format!("{id}: {why}"));
            return;
        }
    };
    let result = run(&case.args);
    tally.ran += 1;
    // The exit code is the verdict.
    if let Ok(out) = serde_json::from_str::<Value>(&result.stdout) {
        if let Some(verified) = out["verified"].as_bool() {
            if (result.code == 0) != verified {
                tally.failed.push(format!(
                    "{id}: exit code {} for verified={verified}",
                    result.code
                ));
            }
        }
    }
    let (want, got) = (expected(&case), project(&case, &result));
    if want != got {
        tally
            .failed
            .push(format!("{id}:\n  expected {want}\n  got      {got}"));
    }
}

fn suites(corpus: Value) -> Vec<Value> {
    match corpus {
        Value::Array(suites) => suites,
        Value::Object(ref map) if map.contains_key("suites") => {
            map["suites"].as_array().cloned().unwrap_or_default()
        }
        other => vec![other],
    }
}

#[test]
fn the_binary_gives_the_reference_verdicts_on_the_shared_vectors() {
    let mut tally = Tally::default();
    for name in [
        "canonical",
        "field_registry",
        "out_of_band",
        "remediation",
        "anchors",
        "audit",
        "grants",
    ] {
        run_suite(&fixture(name), &mut tally);
    }
    assert!(tally.failed.is_empty(), "{}", tally.failed.join("\n"));
    // Every decision, export and record vector, every anchored export, and
    // the audit suite's key histories, exports and packs; the canonical-JSON,
    // timestamp, agreement, anchor-chain, key-window and completeness vectors
    // are the SDK's own tests (tests/anchors.rs, tests/audit.rs). 1.6.0: the
    // grants suite's records and stores; its envelopes, issuance and use
    // rules are the SDK's own tests (tests/grants.rs).
    assert_eq!(
        tally.ran,
        10 + 6 + 41 + 31 + 8 + (19 + 13 + 22 + 2 + 13) + (12 + 26),
        "{:#?}",
        tally.skipped
    );
}

#[test]
fn the_binary_verifies_the_reference_export_as_the_na_did() {
    let v = fixture("python-vectors");
    let scratch = Scratch::new("python-vectors");
    let result = run(&[
        "export",
        &scratch.file("export.jsonl", v["export"].as_str().unwrap()),
        "--na-key",
        v["na_public_key"].as_str().unwrap(),
        "--executor-keys",
        &scratch.json("keys.json", &v["executor_keys"]),
        "--json",
    ]);
    assert_eq!(result.code, 0, "{}", result.stdout);
    assert_eq!(result.json(), v["server_verification"]);
}

#[test]
fn the_core_corpus_when_given() {
    let Some(path) = std::env::var_os("GM_VERIFY_CORPUS") else {
        eprintln!("GM_VERIFY_CORPUS is not set: the core's verification corpus is not run");
        return;
    };
    let path = std::path::PathBuf::from(path);
    let mut tally = Tally::default();
    if path.is_dir() {
        let index: Value = serde_json::from_str(
            &std::fs::read_to_string(path.join("corpus.json")).expect("corpus.json is readable"),
        )
        .expect("corpus.json is JSON");
        assert_eq!(index["suite"], "verification");
        for case in index["cases"].as_array().into_iter().flatten() {
            let id = format!("corpus/{}", case["id"].as_str().unwrap_or("?"));
            check(&id, adapt_corpus(case, &path), &mut tally);
        }
        // The suites the corpus copies are this crate's fixtures, unchanged.
        let fixtures = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../tests/fixtures");
        for name in [
            "canonical",
            "field_registry",
            "out_of_band",
            "remediation",
            "audit",
            "grants",
        ] {
            let theirs = std::fs::read(path.join("vectors").join(format!("{name}.json")))
                .expect("the corpus copies the suite");
            let ours = std::fs::read(fixtures.join(format!("{name}.json"))).expect("the fixture");
            // A Windows checkout may hold the fixtures with CRLF.
            let normalize = |b: Vec<u8>| String::from_utf8(b).unwrap().replace("\r\n", "\n");
            assert!(
                normalize(theirs) == normalize(ours),
                "tests/fixtures/{name}.json differs from the core's"
            );
        }
    } else {
        let text = std::fs::read_to_string(&path).expect("the corpus is readable");
        let corpus: Value = serde_json::from_str(&text).expect("the corpus is JSON");
        for suite in suites(corpus) {
            run_suite(&suite, &mut tally);
        }
    }
    eprintln!(
        "corpus: {} vectors ran, {} skipped",
        tally.ran,
        tally.skipped.len()
    );
    for skipped in &tally.skipped {
        eprintln!("  skipped {skipped}");
    }
    assert!(tally.failed.is_empty(), "{}", tally.failed.join("\n"));
    let strict = std::env::var("GM_VERIFY_CORPUS_STRICT").is_ok_and(|s| s == "1");
    assert!(
        !strict || tally.skipped.is_empty(),
        "{} vectors have no adapter",
        tally.skipped.len()
    );
    assert!(tally.ran > 0, "the corpus holds no vector the binary runs");
}
